import "./Landing.css";

const Landing = () => {
    return (
        <div>
            {/* Header */}
            <header>
                <h1>Price Tracker App</h1>
            </header>

            {/* Hero Section */}
            <section>
                <h2>Welcome to the Best Price Tracker</h2>
                <p>Track prices and save money effortlessly.</p>
            </section>

            {/* Features Section */}
            <section>
                <h3>Features</h3>
                <p>Compare prices, get alerts, and view trends.</p>
            </section>

            {/* Footer */}
            <footer>
                <p>&copy; 2026 Price Tracker Project</p>
            </footer>
        </div>
    );
};

export default Landing;
